# scripts/run_gemini_sensitivity.ps1
#
# The section 0.6 stronger-model sensitivity check (docs/04 section 1.0d,
# ADR-047). Four cells -- V0, V3, B3, V5 -- on the frozen 200-question set,
# generated by Gemini Flash on the free tier instead of the local 7B.
#
#   cd "C:\Claude\AI Project"
#   .\scripts\run_gemini_sensitivity.ps1 -DryRun   # every check + the model probe, then stop
#   .\scripts\run_gemini_sensitivity.ps1           # run all four cells
#   .\scripts\run_gemini_sensitivity.ps1 -Only V3  # one cell
#
# WHAT THIS MEASURES: model dependence, not MedQA. Same code, same prompts,
# same retrieval config, same scoring rule, same agent graph, same questions --
# only the generator differs. Never a headline row; never pooled with the
# m=35 / U1-U8 / m_X=7 families.
#
# Refuses to launch unless:
#   1. docs/04 section 1.0d, ADR-047, the frozen question-id manifest and the
#      analysis script are all committed at HEAD and unmodified -- the analysis
#      plan verifiably predates the first API call.
#   2. the frozen question set still hashes to its committed sha256.
#   3. both Gemini configs assert free_tier_only.
#   4. GEMINI_API_KEY is present.
#   5. a model probe confirms which allowlisted model the free tier actually
#      serves AND returns non-empty text; the exact id + API version + UTC date
#      are then stamped into every cell's own results/<run_id>/config.yaml.
#      The probe budget must stay well above the model's reasoning-token usage:
#      gemini-3.8-flash is a thinking model, and the first version of this probe
#      used max_tokens=8, which thinking consumed entirely -- the call
#      "succeeded" with finish_reason=length and empty text, and the gate passed
#      it. An empty reply is now a hard failure.
#
# RESUMING: there is no checkpoint file and none is needed. Every completed LLM
# call is already in .cache/llm/gemini__<model>/, keyed on (model, prompt,
# params). If a daily quota stops the run, relaunch: finished questions replay
# from cache in minutes and the run continues where it stopped. 429s inside a
# run are absorbed by max_retries=8 / backoff_base_s=4.0 (~8 min per call).
#
# ASCII only (8f37955: the PowerShell 5.1 parser chokes on non-ASCII here).

# V3rep is the nondeterminism probe (ADR-047): a SECOND V3 run, descriptive
# only, never tested. It runs last and uses configs/gemini_v3_repeat.yaml,
# whose separate cache_dir forces real API calls instead of replaying run 1.
param(
    [switch]$DryRun,
    [ValidateSet("V0", "V3", "B3", "V5", "V3rep")][string[]]$Only = @("V0", "V3", "B3", "V5", "V3rep")
)

$ErrorActionPreference = "Continue"
$RepoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $RepoRoot
$env:PYTHONIOENCODING = "utf-8"
$env:PYTHONUNBUFFERED = "1"   # ADR-044: stdout reaches the log as it is printed

$IdsPath      = "results/phase7_gemini/question_ids_200.json"
$RegisteredAt = @(
    "docs/04_EVALUATION.md",
    "docs/05_DECISIONS.md",
    $IdsPath,
    "scripts/analysis/gemini_sensitivity_family.py",
    "scripts/freeze_gemini_question_ids.py",
    "configs/gemini_base.yaml",
    "configs/gemini_v5.yaml",
    "configs/gemini_v3_repeat.yaml"
)
# Tried in order; the first the free tier actually serves wins.
$ModelCandidates = @(
    "gemini/gemini-3.8-flash",
    "gemini/gemini-2.5-flash",
    "gemini/gemini-3.5-flash-lite"
)
$ApiVersion = "v1beta"

function Stop-Check([string]$Msg) {
    Write-Host "[gemini_0.6] ABORT -- $Msg"
    exit 1
}

# --- 1. registration predates the run -------------------------------------------
foreach ($f in $RegisteredAt) {
    if (-not (Test-Path $f)) { Stop-Check "$f does not exist" }
    git diff --quiet HEAD -- $f
    if ($LASTEXITCODE -ne 0) { Stop-Check "$f has uncommitted changes -- register before running" }
    $untracked = @(git ls-files --others --exclude-standard -- $f)
    if ($untracked.Count -gt 0) { Stop-Check "$f is untracked -- commit it before running" }
}
git grep -q "1.0d Stronger-model sensitivity check" HEAD -- docs/04_EVALUATION.md
if ($LASTEXITCODE -ne 0) { Stop-Check "docs/04 section 1.0d is not committed at HEAD" }
git grep -q "ADR-047" HEAD -- docs/05_DECISIONS.md
if ($LASTEXITCODE -ne 0) { Stop-Check "ADR-047 is not committed at HEAD" }
Write-Host "[gemini_0.6] registration check PASSED -- plan committed before the first API call"

# --- 2. the frozen question set has not drifted ---------------------------------
uv run python -m scripts.freeze_gemini_question_ids --check
if ($LASTEXITCODE -ne 0) { Stop-Check "frozen question set failed its sha256 check" }

# --- 3. cost guard is actually on in both configs -------------------------------
foreach ($c in @("configs/gemini_base.yaml", "configs/gemini_v5.yaml")) {
    $resolved = uv run python -c "from src.config import load_config; c=load_config('$c'); print(c.llm.free_tier_only); print(len(c.llm.fallback_chain))"
    $lines = @($resolved -split "`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if ($lines[0] -ne "True") { Stop-Check "$c does not set llm.free_tier_only" }
    if ($lines[1] -ne "1") { Stop-Check "$c fallback_chain is not a single entry (nothing may be fallen through to)" }
}
Write-Host "[gemini_0.6] cost guard PASSED -- free_tier_only set, single-entry chain in both configs"

# --- 4. key present -------------------------------------------------------------
uv run python -c "import os,sys; from dotenv import load_dotenv; load_dotenv(); sys.exit(0 if os.environ.get('GEMINI_API_KEY') else 1)"
if ($LASTEXITCODE -ne 0) { Stop-Check "GEMINI_API_KEY is not set (.env or environment)" }

# --- 5. probe which model the free tier serves ----------------------------------
$Model = $null
foreach ($cand in $ModelCandidates) {
    Write-Host "[gemini_0.6] probing $cand ..."
    uv run python -c @"
import sys
from src.config import load_config
from src.llm.client import chat
cfg = load_config('configs/gemini_base.yaml')
cfg.llm.fallback_chain[0].model = '$cand'
if f'gemini:$cand' not in cfg.llm.free_tier_allowed:
    print('not on the free-tier allowlist'); sys.exit(1)
r = chat('Reply with the single word OK.', config=cfg, max_tokens=512)
txt = (r.text or '').strip()
if not txt:
    print('probe returned EMPTY text -- served but produced no visible output'); sys.exit(1)
print('probe reply:', txt[:40])
"@
    if ($LASTEXITCODE -eq 0) { $Model = $cand; break }
    Write-Host "[gemini_0.6]   $cand did not serve -- trying the next candidate"
}
if (-not $Model) { Stop-Check "no allowlisted model was served by the free tier" }
Write-Host "[gemini_0.6] model resolved: $Model (api_version $ApiVersion)"

# --- cells ----------------------------------------------------------------------
# EVERY value-taking flag uses the --flag=value form, deliberately.
#
# `--variant-suffix -gemini` fails: argparse sees a token starting with "-" and
# treats it as a new option rather than this option's value, so all five cells
# died on "argument --variant-suffix: expected one argument" (zero API calls
# made). `--variant-suffix=-gemini` is unambiguous regardless of the leading
# dash. Audited the rest at the same time: --dataset, --split, --seed,
# --question-ids, --llm-model, --llm-api-version, --config, --variant and
# --baselines all currently carry values with no leading dash, so only the
# suffix was actually broken -- but the "=" form is applied uniformly so the
# whole bug class is gone rather than one instance of it. This is a launch-time
# failure that no local check caught, so it is pinned by
# tests/test_launcher_argv.py, which parses the real command strings out of
# THIS file and feeds them to the actual parsers.
$CommonArgs = "--dataset=medqa --split=test --seed=42 --question-ids=$IdsPath --llm-model=$Model --llm-api-version=$ApiVersion"
$H = "uv run python -m src.eval.harness $CommonArgs --variant-suffix=-gemini"
$B = "uv run python -m scripts.run_baselines $CommonArgs --variant-suffix=-gemini"

$Hrep = "uv run python -m src.eval.harness $CommonArgs --variant-suffix=-gemini-rep2"
$AllCells = [ordered]@{
    "V0"    = "$H --config=configs/gemini_base.yaml --variant=V0"
    "V3"    = "$H --config=configs/gemini_base.yaml --variant=V3"
    "B3"    = "$B --config=configs/gemini_base.yaml --baselines=B3"
    "V5"    = "$H --config=configs/gemini_v5.yaml"
    "V3rep" = "$Hrep --config=configs/gemini_v3_repeat.yaml --variant=V3"
}
# run dir prefix per cell -- V3rep writes medqa_V3-gemini-rep2_*, not medqa_V3rep-*
$DirPrefix = @{ "V0" = "V0-gemini"; "V3" = "V3-gemini"; "B3" = "B3-gemini"; "V5" = "V5-gemini"; "V3rep" = "V3-gemini-rep2" }
$Cells = [ordered]@{}
foreach ($name in $AllCells.Keys) { if ($Only -contains $name) { $Cells[$name] = $AllCells[$name] } }

if ($DryRun) {
    Write-Host "[gemini_0.6] DRY RUN -- all checks passed. Would run, in order:"
    foreach ($name in $Cells.Keys) { Write-Host "  [$name]  $($Cells[$name])" }
    exit 0
}

$LogDir = Join-Path $RepoRoot "logs"
New-Item -ItemType Directory -Force -Path $LogDir | Out-Null
$OutDir = Join-Path $RepoRoot "results\phase7_gemini"
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$Stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$StartUtc = (Get-Date).ToUniversalTime()
$Results = @()

function Invoke-Cell {
    param([string]$Name, [string]$Command)
    $LogPath = Join-Path $LogDir "gemini06_$($Name)_$Stamp.log"
    Write-Host ""
    Write-Host "========================================================================"
    Write-Host "[gemini_0.6] START  $Name"
    Write-Host "[gemini_0.6] cmd:   $Command"
    Write-Host "[gemini_0.6] log:   $LogPath"
    Write-Host "========================================================================"
    # ADR-039: stub first, so a zero-stdout failure still leaves a trace.
    "[gemini_0.6] STUB   $Name started $((Get-Date).ToString('u'))`ncmd: $Command" |
        Set-Content -Path $LogPath -Encoding utf8
    $start = Get-Date
    # ADR-044: cmd merges the traceback (stderr) into stdout before PowerShell sees it.
    cmd /c "$Command 2>&1" | Tee-Object -FilePath $LogPath -Append
    $exit = $LASTEXITCODE
    $elapsed = (Get-Date) - $start
    $status = if ($exit -eq 0) { "OK" } else { "FAILED (exit $exit)" }
    Write-Host "[gemini_0.6] DONE   $Name -> $status  ($([math]::Round($elapsed.TotalMinutes,1)) min)"
    if ($exit -ne 0) {
        Write-Host "[gemini_0.6]   a quota stop is resumable: relaunch and finished questions replay from cache."
    }
    $script:Results += [pscustomobject]@{
        Cell = $Name; ExitCode = $exit
        Minutes = [math]::Round($elapsed.TotalMinutes, 1); Log = $LogPath
    }
}

foreach ($name in $Cells.Keys) { Invoke-Cell -Name $name -Command $Cells[$name] }

# --- run dirs this launch produced ----------------------------------------------
$RunDirs = [ordered]@{}
foreach ($name in $Cells.Keys) {
    $d = Get-ChildItem -Path (Join-Path $RepoRoot "results") -Directory -Filter "medqa_$($DirPrefix[$name])_*" |
        Where-Object { $_.LastWriteTimeUtc -ge $StartUtc } |
        Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1
    $RunDirs[$name] = if ($d) { $d.Name } else { $null }
}

# --- manifest -------------------------------------------------------------------
$manifest = [ordered]@{
    check              = "docs/04_EVALUATION.md section 1.0d -- section 0.6 stronger-model sensitivity check (ADR-047)"
    measures           = "model dependence, not MedQA; robustness only, never a headline row"
    launched_utc       = $StartUtc.ToString('u')
    launch_head        = (git rev-parse HEAD).Trim()
    model              = $Model
    model_candidates   = $ModelCandidates
    api_version        = $ApiVersion
    free_tier_only     = $true
    dataset            = "medqa"
    split              = "test"
    n                  = 200
    seed               = 42
    question_ids       = $IdsPath
    cells              = @($Cells.Keys)
    commands           = $Cells
    run_dirs           = $RunDirs
    cell_outcomes      = $Results
    nondeterminism     = "Gemini exposes no seed: these runs are NOT reproducible (ADR-047, docs/00 section 7). temperature pinned to 0.0; V3rep quantifies run-to-run agreement, descriptive only."
    next_steps         = @(
        "uv run python -m scripts.analysis.gemini_sensitivity_family --v0 <dir> --v3 <dir> --b3 <dir> --v5 <dir> --v3-repeat <dir>",
        "fill docs/04 section 5.1 from results/phase7_gemini/gemini_sensitivity_family.json"
    )
}
$manifestPath = Join-Path $OutDir "gemini_launch_$Stamp.json"
$manifest | ConvertTo-Json -Depth 6 | Set-Content -Path $manifestPath -Encoding utf8
Write-Host ""
Write-Host "[gemini_0.6] wrote $manifestPath"
$Results | Format-Table -AutoSize

$failed = $Results | Where-Object { $_.ExitCode -ne 0 }
if ($failed) {
    Write-Host "[gemini_0.6] $($failed.Count) cell(s) FAILED -- inspect the logs before any analysis."
    exit 1
}
Write-Host "[gemini_0.6] all cells OK. Next:"
$AnalysisCmd = "  uv run python -m scripts.analysis.gemini_sensitivity_family --v0 $($RunDirs['V0']) --v3 $($RunDirs['V3']) --b3 $($RunDirs['B3']) --v5 $($RunDirs['V5'])"
if ($RunDirs['V3rep']) { $AnalysisCmd += " --v3-repeat $($RunDirs['V3rep'])" }
Write-Host $AnalysisCmd
Write-Host "[gemini_0.6] reminder: these runs are NOT seed-deterministic (Gemini has no seed) -- never report them as reproducible."
exit 0
